-- Paste into the Studio command bar and press Enter.
local a = game.ReplicatedStorage.Shared.Assets local s = a.Source s = s:gsub("%-%- LOBBY ART START.-%-%- LOBBY ART END\n", "") local block = "-- LOBBY ART START\nAssets.Lobby = Assets.Lobby or {}\nAssets.Lobby.Marble = \"rbxassetid://122431744080246\"\nAssets.Lobby.Carpet = \"rbxassetid://97588975800351\"\nAssets.Lobby.Wall = \"rbxassetid://118217118561749\"\n-- LOBBY ART END\n" local n s, n = s:gsub("\nreturn Assets", function() return "\n" .. block .. "return Assets" end, 1) if n == 1 then a.Source = s print("Lobby textures saved! Press Play.") else warn("Could not find Assets - tell Claude") end
